from typing import List

def _indent(s: str, n: int = 2) -> str:
    pad = " " * n
    return "\n".join(pad + line if line else line for line in s.splitlines())

# Build minimal, valid ietf-yang-library instance data in XML or JSON.
# These inputs are aimed to be accepted by libyang when creating a context from
# yang-library data (ly_ctx_new_ylmem / ly_ctx_new_ylpath) and for lyd_parse_data_*.
# We generate a few schema variants (legacy RFC7895 and RFC8525 1.1 forms) to
# exercise different code paths, and optionally include multiple modules and features.

# Minimal JSON (RFC 8525 YANG Library 1.1) payload
_JSON_TPL = {
    "ietf-yang-library:yang-library": {
        "content-id": "CID",
        "modules-state": {
            "module-set": [
                {
                    "name": "set0",
                    "module": []
                }
            ]
        }
    }
}

# Module JSON entry according to RFC 8525
# name, revision optional, namespace optional, feature list optional

def _json_module(name: str, rev: str | None, ns: str | None, feats: List[str]) -> dict:
    m = {"name": name}
    if rev:
        m["revision"] = rev
    if ns:
        m["namespace"] = ns
    if feats:
        m["feature"] = feats
    # schema location can be given via schema; leave out to keep minimal but valid
    return m

# Minimal XML (RFC 8525) payload
_XML_HEADER = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>"
_XML_NS = {
    "yl": "urn:ietf:params:xml:ns:yang:ietf-yang-library",
}

def _xml_escape(s: str) -> str:
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;").replace("'", "&apos;")

def _xml_build(mods: List[dict], content_id: str) -> str:
    # Build minimal RFC 8525 layout
    # yang-library/content-id + modules-state/module-set/module*
    parts = [
        _XML_HEADER,
        f"<yl:yang-library xmlns:yl=\"{_XML_NS['yl']}\">",
        f"  <yl:content-id>{_xml_escape(content_id)}</yl:content-id>",
        "  <yl:modules-state>",
        "    <yl:module-set>",
        "      <yl:name>set0</yl:name>",
    ]
    for m in mods:
        parts.append("      <yl:module>")
        parts.append(f"        <yl:name>{_xml_escape(m['name'])}</yl:name>")
        if m.get("revision"):
            parts.append(f"        <yl:revision>{_xml_escape(m['revision'])}</yl:revision>")
        if m.get("namespace"):
            parts.append(f"        <yl:namespace>{_xml_escape(m['namespace'])}</yl:namespace>")
        for f in m.get("feature", []) or []:
            parts.append(f"        <yl:feature>{_xml_escape(f)}</yl:feature>")
        parts.append("      </yl:module>")
    parts += [
        "    </yl:module-set>",
        "  </yl:modules-state>",
        "</yl:yang-library>",
    ]
    return "\n".join(parts)

# A tiny helper to produce plausible module names, ns and revisions
_MOD_BASES = [
    ("ietf-interfaces", "urn:ietf:params:xml:ns:yang:ietf-interfaces"),
    ("ietf-ip", "urn:ietf:params:xml:ns:yang:ietf-ip"),
    ("iana-if-type", "urn:ietf:params:xml:ns:yang:iana-if-type"),
    ("example-acl", "urn:example:acl"),
    ("example-logger", "urn:example:logger"),
]
_FEATURES = ["foo", "bar", "baz", "experimental", "fast-path"]

def _rand_rev(rng: random.Random) -> str:
    # Generate YYYY-MM-DD within a reasonable range
    year = rng.randint(2008, 2025)
    month = rng.randint(1, 12)
    day = rng.randint(1, 28)
    return f"{year:04d}-{month:02d}-{day:02d}"

def _build_json_payload(rng: random.Random) -> bytes:
    data = json.loads(json.dumps(_JSON_TPL))  # deep copy
    mods: List[dict] = []
    n = rng.randint(1, 4)
    chosen = rng.sample(_MOD_BASES, k=n)
    for name, ns in chosen:
        # Randomly pick to include revision/namespace/features
        rev = _rand_rev(rng) if rng.random() < 0.85 else None
        use_ns = ns if rng.random() < 0.9 else None
        feats = []
        if rng.random() < 0.6:
            feats = rng.sample(_FEATURES, k=rng.randint(0, min(3, len(_FEATURES))))
        mods.append(_json_module(name, rev, use_ns, feats))
    data["ietf-yang-library:yang-library"]["content-id"] = f"cid-{rng.randrange(1<<30)}"
    data["ietf-yang-library:yang-library"]["modules-state"]["module-set"][0]["module"] = mods
    s = json.dumps(data, separators=(",", ":"))
    return s.encode("utf-8")

def _build_xml_payload(rng: random.Random) -> bytes:
    n = rng.randint(1, 4)
    chosen = rng.sample(_MOD_BASES, k=n)
    mods = []
    for name, ns in chosen:
        m = {"name": name}
        if rng.random() < 0.9:
            m["revision"] = _rand_rev(rng)
        if rng.random() < 0.85:
            m["namespace"] = ns
        if rng.random() < 0.6:
            m["feature"] = rng.sample(_FEATURES, k=rng.randint(0, min(3, len(_FEATURES))))
        mods.append(m)
    content_id = f"cid-{rng.randrange(1<<30)}"
    return _xml_build(mods, content_id).encode("utf-8")

# LYB (libyang binary) is opaque; generating truly valid LYB yang-library payload is non-trivial
# without libyang helpers. We therefore prefer XML/JSON which the stubs select via format.
# However, ly_ctx_new_ylpath may attempt to read by extension; the harness provides the filename.
# Our generator returns the buffer for FUZZ_PARAM_STR and file contents for FUZZ_PARAM_FILENAME.

# To increase coverage, sometimes prepend or append benign whitespace/comments (JSON) or XML comments.

def _decorate(rng: random.Random, data: bytes, kind: str) -> bytes:
    if kind == "json":
        prefix = "" if rng.random() < 0.7 else "\n\n"
        suffix = "" if rng.random() < 0.7 else "\n\n"
        return (prefix.encode() + data + suffix.encode())
    elif kind == "xml":
        # Optional XML comment decoration
        if rng.random() < 0.5:
            cmt = f"<!-- generated {rng.randrange(1<<16)} -->\n"
            return (cmt.encode() + data)
        return data
    return data

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose between JSON and XML with a slight bias to JSON (common in RESTCONF)
    kind = "json" if rng.random() < 0.6 else "xml"
    if kind == "json":
        payload = _build_json_payload(rng)
    else:
        payload = _build_xml_payload(rng)
    payload = _decorate(rng, payload, kind)
    # Ensure size limit
    if len(payload) > 4096:
        payload = payload[:4096]
    return payload

import random
import struct
import itertools

# Generator for an arbitrary bytes buffer tailored to the libyang fuzz stubs listed.
# Goals:
# - Produce valid, interesting byte sequences that exercise different code paths.
# - Include mixtures of text-like content (YANG identifiers, numbers, XPath, JSON-ish),
#   raw binary, and lengths ranging from empty to moderate, capped to 4096 bytes.
# - Be deterministic with respect to the provided seed, but still varied across calls.

_MAX_SIZE = 4096

# Some canonical fragments useful across stubs
_YANG_IDENTIFIERS = [
    b"module", b"container", b"list", b"leaf", b"leaf-list", b"choice", b"case",
    b"rpc", b"action", b"notification", b"uses", b"grouping", b"type", b"typedef",
    b"when", b"must", b"pattern", b"range", b"default", b"key", b"presence"
]
_JSON_FRAGMENTS = [
    b"{}", b"[]", b"{\"a\":1}", b"{\"ns:leaf\":\"val\"}", b"{\"mod:name\":true}",
    b"{\"k\":[1,2,3]}", b"{\"nested\":{\"x\":\"y\"}}"
]
_XML_FRAGMENTS = [
    b"<a/>", b"<m:l xmlns:m=\"urn:mod\">t</m:l>", b"<rpc/>", b"<notif t=\"1\"/>"
]
_XPATH_TOKENS = [
    b"/", b"//", b"..", b".", b"*", b"text()", b"node()", b"@attr", b"name()",
    b"/m:top/m:cont/m:list[key='v']", b"/if:interfaces/if:interface[name='eth0']"
]
_NUMERIC_STRINGS = [
    b"0", b"1", b"-1", b"10", b"1234567890", b"0x10", b"+42", b"-9223372036854775808",
    b"18446744073709551615", b"3.14159", b"-0.0001", b"1e10"
]
_WORDS = [
    b"alpha", b"beta", b"gamma", b"delta", b"epsilon", b"zeta", b"eta", b"theta", b"iota",
    b"true", b"false", b"null", b"NaN"
]
_SEPARATORS = [b" ", b"\t", b"\n", b",", b";", b"|", b"&", b"::", b":", b"=", b"/", b"[", b"]", b"(", b")"]

# Helpful builders

def _rand_int(rng, a, b):
    return rng.randint(a, b)

def _maybe(rng, p=0.5):
    return rng.random() < p

def _repeat_join(parts, rng, min_times=1, max_times=5, sep=b""):
    times = _rand_int(rng, min_times, max_times)
    chosen = [rng.choice(parts) for _ in range(times)]
    return sep.join(chosen)

def _random_binary(rng, min_len=0, max_len=512):
    n = _rand_int(rng, min_len, max_len)
    # Mix ASCII, zero bytes, and high bytes
    out = bytearray()
    for _ in range(n):
        t = rng.random()
        if t < 0.6:
            out.append(rng.randint(0x20, 0x7E))  # printable
        elif t < 0.8:
            out.append(0)  # NUL
        else:
            out.append(rng.randint(0x80, 0xFF))  # high-bit
    return bytes(out)

def _make_candidate_yang_like(rng):
    parts = []
    if _maybe(rng):
        parts.append(b"module "+ rng.choice(_WORDS) + b" {\n  namespace \"urn:" + rng.choice(_WORDS) + b"\";\n  prefix m;\n}")
    # Data tree-ish
    if _maybe(rng):
        parts.append(b"m:top { m:leaf '" + rng.choice(_WORDS) + b"'; }")
    # Identifiers
    parts.append(_repeat_join(_YANG_IDENTIFIERS + _WORDS, rng, 2, 6, sep=b" "))
    return b"\n".join(parts)

def _make_candidate_xpath(rng):
    base = _repeat_join(_XPATH_TOKENS, rng, 1, 4, sep=b"")
    if _maybe(rng):
        base += b"[position()=1]"
    if _maybe(rng):
        base = b"/m:root" + base
    return base

def _make_candidate_json_like(rng):
    base = rng.choice(_JSON_FRAGMENTS)
    if _maybe(rng):
        # insert a namespaced-like key
        base += b"\n{\"" + rng.choice(_WORDS) + b":" + rng.choice(_WORDS) + b"\":\"v\"}"
    return base

def _make_candidate_xml_like(rng):
    base = rng.choice(_XML_FRAGMENTS)
    if _maybe(rng):
        base += b"\n<" + rng.choice(_WORDS) + b"/>"
    return base

def _make_candidate_numeric(rng):
    s = rng.choice(_NUMERIC_STRINGS)
    if _maybe(rng):
        s += rng.choice([b" ", b"\n"]) + rng.choice(_NUMERIC_STRINGS)
    return s

def _make_hash_inputs(rng):
    # Build multiple parts for lyht_hash_multi paths
    p1 = _repeat_join(_WORDS + _YANG_IDENTIFIERS, rng, 1, 4, sep=rng.choice(_SEPARATORS))
    p2 = _make_candidate_numeric(rng)
    p3 = _random_binary(rng, 0, 64)
    return p1 + b"\n" + p2 + b"\n" + p3

def _compose_segments(rng):
    # Compose multiple themed segments to increase code coverage across stubs
    segments = []
    # Ensure some are NUL-terminated friendly; others binary-only
    builders = [
        _make_candidate_yang_like,
        _make_candidate_xpath,
        _make_candidate_json_like,
        _make_candidate_xml_like,
        _make_candidate_numeric,
    ]
    rng.shuffle(builders)
    for bld in builders:
        if _maybe(rng, 0.85):
            segments.append(bld(rng))
    # Add separators and random binary chunk
    if _maybe(rng, 0.9):
        segments.append(_repeat_join(_SEPARATORS, rng, 3, 10, sep=b""))
    if _maybe(rng, 0.7):
        segments.append(_random_binary(rng, 0, 256))
    # Add hash-oriented materials
    if _maybe(rng, 0.7):
        segments.append(_make_hash_inputs(rng))
    # Optionally embed NULs between segments to test len-based paths
    joined = bytearray()
    for idx, seg in enumerate(segments):
        joined.extend(seg)
        if idx + 1 < len(segments):
            if _maybe(rng, 0.4):
                joined.append(0)  # NUL separator
            else:
                joined.extend(b"\n")
    return bytes(joined)

def _trim_to_limit(b: bytes) -> bytes:
    if len(b) <= _MAX_SIZE:
        return b
    return b[:_MAX_SIZE]

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide high-level profile to bias the buffer toward specific stubs
    profile = rng.choice([
        "dict_nul_or_len",   # mixtures suitable for lydict_insert
        "xpath_print_token", # tokens for xpath printing
        "prefix_data_json",  # JSON-like with prefixes
        "lypath_new",        # instance-identifier-like strings
        "numbers_and_ranges",# strings with numbers for parse_int/uint/dec64
        "hash_heavy",        # content for lyht_hash and multi
        "mixed"               # all mixed
    ])

    if profile == "dict_nul_or_len":
        # Provide a segment that is valid under strlen and also contains embedded NULs for len>0 path
        text = _repeat_join(_WORDS + _YANG_IDENTIFIERS, rng, 3, 10, sep=b" ")
        binpart = _random_binary(rng, 5, 64)
        buf = text + b"\0" + binpart
    elif profile == "xpath_print_token":
        toks = [_make_candidate_xpath(rng) for _ in range(_rand_int(rng, 1, 5))]
        sep = rng.choice([b"", b" ", b"::", b"|"])
        buf = sep.join(toks)
    elif profile == "prefix_data_json":
        # multiple JSON objects with namespaced-like keys
        items = [
            b"{\"mod:name\":\"val\"}",
            b"{\"m:leaf\":123}",
            b"{\"ns:key\":true}",
            b"{\"array\":[1,2,3]}"
        ]
        rng.shuffle(items)
        buf = b"\n".join(items + [rng.choice(_JSON_FRAGMENTS)])
    elif profile == "lypath_new":
        # Build a few instance-identifier-like paths
        candidates = [
            b"/mod:top/cont/list[key='v']/leaf",
            b"/if:interfaces/if:interface[name='eth0']/if:name",
            b"/a:b/c:d[e='1']/f:g",
        ]
        if _maybe(rng):
            candidates.append(_make_candidate_xpath(rng))
        rng.shuffle(candidates)
        buf = b"\n".join(candidates)
    elif profile == "numbers_and_ranges":
        nums = [_make_candidate_numeric(rng) for _ in range(_rand_int(rng, 2, 8))]
        buf = b" ".join(nums)
    elif profile == "hash_heavy":
        buf = _make_hash_inputs(rng) + b"\n" + _random_binary(rng, 32, 256)
    else:  # mixed
        buf = _compose_segments(rng)

    # Occasionally pad or prefix to test offsets and non-NUL terminated buffers
    if _maybe(rng, 0.4):
        pad_len = _rand_int(rng, 0, 32)
        pad = bytes(rng.getrandbits(8) for _ in range(pad_len))
        if _maybe(rng):
            buf = pad + buf
        else:
            buf = buf + pad

    # Ensure maximum size
    buf = _trim_to_limit(buf)
    return buf

import random
import string
from typing import List, Tuple

# Generator for YANG list keys predicate strings used by libyang APIs such as lyd_new_list2()
# We try to create valid key-predicate strings like:
#   [key='value'][other-key="value2"][flag=true]
# Cover a variety of YANG base types and escaping patterns.

KEY_NAME_CHARS = string.ascii_letters + string.digits + "-_"

# Some common YANG-ish key names to increase chance of matching schemas
COMMON_KEYS = [
    "name", "id", "index", "type", "enabled", "admin-status", "oper-status",
    "address", "ipv4", "ipv6", "port", "priority", "mode", "state", "speed",
    "key", "user", "interface", "if-name", "if-index", "vlan", "slot", "card",
]

# Example identity-like values and module-qualified values
IDENTITY_VALUES = [
    "up", "down", "testing", "active", "inactive",
]
MODULES = [
    "ietf-interfaces", "ietf-ip", "ietf-routing", "openconfig-interfaces", "example-mod",
]

# Some IPv4/IPv6 samples
IPV4_SAMPLES = [
    "192.0.2.1", "198.51.100.10", "203.0.113.77", "10.0.0.1", "172.16.1.5", "192.168.1.100",
]
IPV6_SAMPLES = [
    "2001:db8::1", "2001:db8:85a3::8a2e:370:7334", "::1", "fe80::1",
]

# Some integer and boolean samples
INT_SAMPLES = [0, 1, 2, 10, 42, 100, 65535, 2147483647]
BOOL_SAMPLES = ["true", "false"]

# Strings with escaping and various lengths
BASIC_WORDS = [
    "alpha", "beta", "gamma", "delta", "router", "switch", "port-1", "xe-0/0/0",
    "ge-1/0/0", "core", "edge", "customer", "tenant", "region-1",
]

ESCAPE_FRAGMENTS = [
    "O'Reilly", 'He said "hi"', "line\\break", "path\\to\\file", "quote'quote", 'dq"dq',
]

HEX_BYTES = "0123456789abcdef"


def _rand_key_name(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return rng.choice(COMMON_KEYS)
    n = rng.randint(1, 16)
    return rng.choice(string.ascii_lowercase) + ''.join(rng.choice(KEY_NAME_CHARS) for _ in range(n-1))


def _quote_value(val: str, rng: random.Random) -> str:
    # Choose single or double quotes, escaping accordingly
    if rng.random() < 0.5:
        q = "'"
        escaped = val.replace("\\", "\\\\").replace("'", "\\'")
    else:
        q = '"'
        escaped = val.replace("\\", "\\\\").replace('"', '\\"')
    return f"{q}{escaped}{q}"


def _rand_string_value(rng: random.Random) -> str:
    # Mix basic words, escaped fragments, hex-like strings
    choice = rng.random()
    if choice < 0.4:
        s = rng.choice(BASIC_WORDS)
    elif choice < 0.7:
        s = rng.choice(ESCAPE_FRAGMENTS)
    else:
        # hex-ish or random ascii
        if rng.random() < 0.6:
            n = rng.randint(2, 16)
            s = ''.join(rng.choice(HEX_BYTES) for _ in range(n))
        else:
            n = rng.randint(3, 12)
            s = ''.join(rng.choice(string.ascii_letters + string.digits + "-_./:") for _ in range(n))
    return _quote_value(s, rng)


def _rand_identity_value(rng: random.Random) -> str:
    if rng.random() < 0.6:
        # Bare enum/identity token
        return rng.choice(IDENTITY_VALUES)
    # Module-qualified form (JSON rules for identityref often use module-name as prefix)
    return f"{rng.choice(MODULES)}:{rng.choice(IDENTITY_VALUES)}"


def _rand_ip_value(rng: random.Random) -> str:
    if rng.random() < 0.7:
        val = rng.choice(IPV4_SAMPLES)
    else:
        val = rng.choice(IPV6_SAMPLES)
    return _quote_value(val, rng)


def _rand_int_value(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return str(rng.choice(INT_SAMPLES))
    return str(rng.randint(0, 2**31 - 1))


def _rand_bool_value(rng: random.Random) -> str:
    return rng.choice(BOOL_SAMPLES)


def _rand_key_value_pair(rng: random.Random) -> Tuple[str, str]:
    key = _rand_key_name(rng)
    # Decide a type flavor
    t = rng.random()
    if t < 0.30:
        val = _rand_string_value(rng)
    elif t < 0.50:
        val = _rand_int_value(rng)
    elif t < 0.65:
        val = _rand_bool_value(rng)
    elif t < 0.80:
        val = _rand_identity_value(rng)
    else:
        val = _rand_ip_value(rng)
    return key, val


def build_keys_predicate(rng: random.Random, min_keys: int = 1, max_keys: int = 3) -> str:
    n = rng.randint(min_keys, max_keys)
    parts = []
    used = set()
    for _ in range(n):
        key, val = _rand_key_value_pair(rng)
        # Avoid duplicate key predicates
        tries = 0
        while key in used and tries < 5:
            key, val = _rand_key_value_pair(rng)
            tries += 1
        used.add(key)
        parts.append(f"[{key}={val}]")
    return ''.join(parts)


def build_list_name(rng: random.Random) -> str:
    # Prefer realistic names, else synthesize
    if rng.random() < 0.7:
        return rng.choice([
            "interfaces", "interface", "neighbor", "route", "routes", "vrf", "vlan",
            "user", "users", "address", "addresses", "subinterface", "sensor", "module",
            "card", "slot", "acl", "rule", "policy", "prefix", "server",
        ])
    n = rng.randint(3, 16)
    return rng.choice(string.ascii_lowercase) + ''.join(rng.choice(KEY_NAME_CHARS) for _ in range(n-1))


def build_filename_like(rng: random.Random) -> bytes:
    # For FUZZ_PARAM_FILENAME: simple valid content for potential file-backed inputs if used elsewhere
    name = ''.join(rng.choice(string.ascii_letters + string.digits + "-_./") for _ in range(rng.randint(5, 20)))
    return name.encode('utf-8')


def assemble_corpus_items(rng: random.Random) -> List[bytes]:
    items: List[bytes] = []

    # 1) For lyd_new_list2: name string then keys string
    for _ in range(6):
        name = build_list_name(rng)
        # Sometimes generate empty keys (key-less list); sometimes 1..3 keys
        if rng.random() < 0.25:
            keys = ""
        else:
            keys = build_keys_predicate(rng, 1, rng.choice([1, 2, 3]))
        # Separate entries with a newline; the harness typically pulls separate parameters, but we
        # provide several candidate strings concatenated with NULs to allow the fuzzer infra to split.
        items.append(name.encode('utf-8'))
        items.append(keys.encode('utf-8'))

    # 2) For lyd_find_sibling_val: only a value/predicate string; include both full predicates and raw values
    for _ in range(6):
        mode = rng.random()
        if mode < 0.5:
            kval = build_keys_predicate(rng, 1, rng.choice([1, 2, 3]))
        else:
            # raw value string (e.g., for simple leaf-list or single-key lookup)
            _, val = _rand_key_value_pair(rng)
            kval = val
        items.append(kval.encode('utf-8'))

    # 3) A few filename-like entries for any FUZZ_PARAM_FILENAME usage
    for _ in range(3):
        items.append(build_filename_like(rng))

    return items


def pack_items(items: List[bytes], max_total: int = 4096) -> bytes:
    # Concatenate items with NUL separators; these are commonly used by fuzz drivers
    out = bytearray()
    first = True
    for it in items:
        if not first:
            sep = b"\x00"
            if len(out) + len(sep) > max_total:
                break
            out += sep
        first = False
        if len(out) + len(it) > max_total:
            # truncate politely at boundary
            remaining = max_total - len(out)
            out += it[:max(0, remaining)]
            break
        out += it
    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    items = assemble_corpus_items(rng)
    return pack_items(items)

import random
from typing import List, Tuple

# Generator for libyang "XPath expression (JSON-prefixed)" strings.
# The fuzzer stubs call FUZZ_PARAM_STR() to obtain an XPath string used by
# lys_find_xpath_atoms() / lys_find_xpath(). We therefore focus on producing
# valid, interesting XPath expressions using JSON-style prefixes (module names
# as prefixes) per libyang conventions.
#
# We return bytes; callers will pass this buffer as the initial seed for
# FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME in the harness.

MODULES = [
    "ietf-interfaces", "ietf-ip", "iana-if-type", "ietf-yang-library",
    "ietf-system", "example-mod", "ex", "modA", "modB"
]

# Common node names likely present in example models; even if not present,
# expressions remain syntactically valid and exercise different code paths
# (absolute, relative, predicates, functions, operators).
NODES = [
    "interfaces", "interface", "name", "enabled", "type", "description",
    "ipv4", "ipv6", "address", "prefix-length", "mtu", "admin-status",
    "oper-status", "system", "contact", "hostname", "location"
]

# Attribute-like names and list keys typically used in predicates
PRED_KEYS = ["name", "type", "address", "prefix-length", "if-index"]

# XPath functions commonly supported
XPF = [
    "count", "string", "number", "boolean", "starts-with", "contains",
    "normalize-space", "concat", "name", "local-name"
]

AXES = [
    "child", "descendant", "descendant-or-self", "parent", "self",
    "following-sibling", "preceding-sibling", "following", "preceding",
    "ancestor", "ancestor-or-self"
]

OPS = ["=", "!=", "<", "<=", ">", ">="]


def rnd_choice(r: random.Random, seq: List[str]) -> str:
    return r.choice(seq)


def rnd_name(r: random.Random) -> str:
    # 70% pick from known nodes, 30% synthesize an identifier
    if r.random() < 0.7:
        return rnd_choice(r, NODES)
    # synthesize: [a-z][a-z0-9-]{1,12}
    first = r.choice("abcdefghijklmnopqrstuvwxyz")
    rest = "".join(r.choice("abcdefghijklmnopqrstuvwxyz0123456789-") for _ in range(r.randint(1, 12)))
    return first + rest


def prefixed(r: random.Random, name: str | None = None) -> str:
    mod = rnd_choice(r, MODULES)
    if name is None:
        name = rnd_name(r)
    return f"{mod}:{name}"


def literal_string(r: random.Random) -> str:
    # Use single quotes per XPath; escape by using alternating quote styles if needed
    samples = [
        "eth0", "ge-0/0/0", "Loopback0", "up", "down", "true", "false",
        "2001:db8::1", "192.0.2.1", "example", "NULL", "admin"
    ]
    s = rnd_choice(r, samples)
    # Occasionally generate a random token
    if r.random() < 0.3:
        s = "".join(r.choice("abcdefghijklmnopqrstuvwxyz0123456789-._:") for _ in range(r.randint(1, 12)))
    # Choose quoting style to avoid inner quotes
    if "'" in s and '"' not in s:
        return f'"{s}"'
    else:
        return f"'{s}'"


def numeric_literal(r: random.Random) -> str:
    if r.random() < 0.7:
        return str(r.randint(0, 65535))
    # decimal
    return f"{r.randint(0, 9999)}.{r.randint(0, 9999)}"


def predicate_eq(r: random.Random) -> str:
    # [mod:key = 'val'] or [key = number] or function comparisons
    left = prefixed(r, rnd_choice(r, PRED_KEYS)) if r.random() < 0.7 else rnd_choice(r, PRED_KEYS)
    op = rnd_choice(r, OPS)
    if r.random() < 0.6:
        right = literal_string(r)
    else:
        right = numeric_literal(r)
    return f"[{left} {op} {right}]"


def predicate_pos(r: random.Random) -> str:
    # [position()=N] or [N]
    n = r.randint(1, 4)
    if r.random() < 0.5:
        return f"[position()={n}]"
    return f"[{n}]"


def predicate_exists(r: random.Random) -> str:
    # [mod:leaf] existence
    return f"[{prefixed(r)}]"


def any_predicate(r: random.Random) -> str:
    return rnd_choice(r, [predicate_eq, predicate_pos, predicate_exists])(r)


def step(r: random.Random) -> str:
    # possibly axis::prefixed-name with predicates
    name = prefixed(r)
    if r.random() < 0.2:
        axis = rnd_choice(r, AXES)
        core = f"{axis}::{name}"
    else:
        core = name
    preds = "".join(any_predicate(r) for _ in range(r.randint(0, 2)))
    return core + preds


def function_call(r: random.Random) -> str:
    fn = rnd_choice(r, XPF)
    if fn in ("count", "string", "number", "boolean", "name", "local-name"):
        arg = step(r) if r.random() < 0.6 else prefixed(r)
    elif fn in ("starts-with", "contains"):
        arg = f"{prefixed(r)}, {literal_string(r)}"
    elif fn == "concat":
        parts = [literal_string(r) for _ in range(r.randint(2, 4))]
        arg = ", ".join(parts)
    else:
        arg = prefixed(r)
    return f"{fn}({arg})"


def build_absolute_path(r: random.Random) -> str:
    # /mod:top/mod:child/... with optional predicates
    depth = r.randint(1, 4)
    parts = ["" ]  # leading slash
    for _ in range(depth):
        parts.append(step(r))
    return "/" + "/".join(parts[1:])


def build_relative_path(r: random.Random) -> str:
    # .., ., ancestor axes occasionally; otherwise simple chain
    segs: List[str] = []
    if r.random() < 0.3:
        segs.append(".")
    if r.random() < 0.3:
        segs.extend([".."] * r.randint(1, 2))
    for _ in range(r.randint(1, 4)):
        segs.append(step(r))
    return "/".join(segs)


def build_union_or_expr(r: random.Random) -> str:
    # Combine paths with | or use comparisons/functions
    base = build_absolute_path(r) if r.random() < 0.6 else build_relative_path(r)
    choice = r.random()
    if choice < 0.33:
        return base
    if choice < 0.66:
        # union
        other = build_absolute_path(r) if r.random() < 0.5 else build_relative_path(r)
        return f"{base} | {other}"
    # comparison at end: path[cond] or function
    if r.random() < 0.5:
        return f"{base}[{function_call(r)} {rnd_choice(r, OPS)} {numeric_literal(r)}]"
    else:
        return function_call(r)


def ensure_size(s: str, max_len: int = 512) -> str:
    if len(s) <= max_len:
        return s
    # Truncate conservatively at a step boundary (slash) if possible
    cut = s.rfind('/', 0, max_len)
    if cut == -1:
        return s[:max_len]
    return s[:cut]


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Build a small corpus of diverse expressions and then pick one to return.
    builders = [
        build_absolute_path,
        build_relative_path,
        build_union_or_expr,
    ]

    # Create between 1 and 3 expressions concatenated by newline to allow
    # harnesses that read multiple cases; still valid when single is expected
    # because readers often stop at first NUL/line. Keep total under 4 KiB.
    exprs: List[str] = []
    for _ in range(r.randint(1, 3)):
        b = rnd_choice(r, builders)
        expr = ensure_size(b(r))
        exprs.append(expr)

    payload = "\n".join(exprs)
    data = payload.encode("utf-8")
    if len(data) > 4096:
        data = data[:4096]
    return data
